/** Photographs actually shot in this locality. May be empty — never fake it. */
export const workForArea = (slug: string): WorkImage[] =>
  WORK.filter((w) => w.areaSlug === slug);

export const workForService = (slug: string): WorkImage[] =>
  WORK.filter((w) => w.service === slug);

export const workForOccasion = (occasion: string): WorkImage[] =>
  WORK.filter((w) => w.occasion === occasion);

export const OCCASIONS = Array.from(new Set(WORK.map((w) => w.occasion))).sort();

/* ------------------------------------------------------------------ *
 * Choosing what a locality page shows.
 *
 * A photograph may be DISPLAYED on any page. It may only be CLAIMED by
 * the page whose areaSlug it carries. Those are different things, and
 * conflating them produced the doorway-page problem fixed in a62db2e:
 * one shared photo set sat under "Recent setups in {area}" on thirty
 * pages, so the same images asserted thirty neighbourhoods.
 *
 *   local  - shot in this locality. Heading may name the area.
 *   nearby - shot elsewhere or location unverified. Heading must NOT
 *            name the page's area. Each image keeps its own true area
 *            in its caption, which is honest and earns an internal link.
 *
 * The nearby set is scattered by a slug-derived offset AND stride, so no
 * two locality pages render the same grid from the shared pool. An
 * offset alone was not enough - neighbouring offsets collided once the
 * one-per-occasion filter was applied.
 * ------------------------------------------------------------------ */

/** Stable, non-cryptographic hash. The same slug always yields the same grid. */
function slugOffset(slug: string): number {
  let h = 2166136261;
  for (let i = 0; i < slug.length; i += 1) {
    h ^= slug.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return Math.abs(h);
}

export type LocalityWork = {
  /** Shot in this locality. Safe to caption with the area name. */
  local: WorkImage[];
  /** Shot elsewhere. Never caption these with the page's area. */
  nearby: WorkImage[];
  /** True when `local` is empty, so the heading drops the area name. */
  cityWideOnly: boolean;
};

const MIN_TILES = 6;

export function workShownOn(slug: string): LocalityWork {
  const local = workForArea(slug);
  if (local.length >= MIN_TILES) {
    return { local, nearby: [], cityWideOnly: false };
  }

  const pool = WORK.filter((w) => w.areaSlug !== slug);
  const want = MIN_TILES - local.length;
  const n = pool.length;
  const h = slugOffset(slug);
  const start = h % Math.max(n, 1);

  const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b));
  let stride = (h % Math.max(n - 1, 1)) + 1;
  while (n > 1 && gcd(stride, n) !== 1) stride = (stride % (n - 1)) + 1;

  const picked: WorkImage[] = [];
  const seenOccasions = new Set<string>();
  for (let pass = 0; pass < 2 && picked.length < want; pass += 1) {
    for (let i = 0; i < n && picked.length < want; i += 1) {
      const w = pool[(start + i * stride) % n];
      if (picked.includes(w)) continue;
      // First pass spreads occasions so a page is not six haldi stages.
      if (pass === 0 && seenOccasions.has(w.occasion)) continue;
      seenOccasions.add(w.occasion);
      picked.push(w);
    }
  }

  return { local, nearby: picked, cityWideOnly: local.length === 0 };
}

/** Heading copy that cannot accidentally claim a location. */
export function workHeading(slug: string, areaName: string): string {
  return workForArea(slug).length > 0
    ? `Our work in ${areaName}`
    : 'Our work across Bengaluru';
}

/** Full Cloudinary URL for an image. */
export const workUrl = (w: WorkImage): string => `${CLOUDINARY_BASE}${w.file}`;
